"""Entirely generated byte journals and SQLite receipts; no incident fixture."""

import json
import os
import sqlite3

import pytest

from argus.core.accounting_integrity import AccountingIntegrityError, strict_jsonl
from argus.core.incident_recovery import OfflineRecovery, digest, validate_recovered
from argus.core.usage import UsageRecord, summarize_usage, usage_recorded_event


def encoded(row):
    return json.dumps(row, sort_keys=True).encode() + b"\n"


@pytest.fixture(params=[("synthetic-alpha", 41, 0.25), ("synthetic-beta", 73, 0.75)])
def case(tmp_path, request):
    project, receipt_id, charge = request.param
    source = "/offline-source/projects/" + project  # identity only; never opened
    model = dict(
        session_id="known-session",
        model="synthetic-model",
        input_tokens=11,
        cached_input_tokens=2,
        cache_write_tokens=0,
        output_tokens=3,
        reasoning_output_tokens=0,
        total_nano_aiu=int(charge * 100_000_000_000),
        created_at="12",
        usage_event_id=receipt_id,
        cost_usd=charge,
    )
    known = UsageRecord.from_jsonable(
        dict(
            call_id="known-call",
            project_id=project,
            provider="copilot",
            model="synthetic-model",
            run_label="test",
            status="completed",
            started_at=10,
            completed_at=15,
            pricing_status="priced",
            cost_usd=charge,
            input_tokens=11,
            cached_input_tokens=2,
            cache_write_tokens=0,
            output_tokens=3,
            reasoning_output_tokens=0,
            total_nano_aiu=model["total_nano_aiu"],
            model_usage=[model],
        )
    )
    reservation = dict(
        id="legacy-reservation",
        call_id="unknown-call",
        project_id=project,
        project_root=source,
        provider="copilot",
        model="synthetic-model",
        run_label="test",
        created_at=10,
        pid=4242,
        amount_usd=2.0,
        observed_cost_usd=0.125,
        observed_tokens=9,
    )
    ack = dict(project_id=project, liability_usd=3, reason="Synthetic existing approval")
    state = dict(
        version=3,
        day="2000-01-01",
        updated_at=20,
        project_roots=[source],
        reservations=[reservation],
        unresolved=[],
        acknowledgements={"older-call": ack},
    )
    prefix = b'{"call_id":"unknown-call","error":"truncated'
    usage = prefix + encoded(known.to_jsonable())
    part1 = b'{"type":"provider.request.completed","call_id":"known-call","error":"broken'
    part2 = b'{"type":"life.planner.start","partial":'
    events = part1 + encoded(usage_recorded_event(known))
    second_offset = len(events)
    events += part2 + encoded(dict(type="synthetic.retained", ts=11))
    events += encoded(
        dict(
            type="provider.request.started",
            call_id="unknown-call",
            provider="copilot",
            run_label="test",
            ts=11,
        )
    )
    events += encoded(
        dict(
            type="budget.reservation.created",
            reservation_id="legacy-reservation",
            call_id="unknown-call",
            provider="copilot",
            model="synthetic-model",
            amount_usd=2.0,
            run_label="test",
            ts=10,
        )
    )
    events += encoded(
        dict(
            type="agent.io.complete",
            call_id="unknown-call",
            turn_failed=True,
            thread_id="unknown-session",
            backend="copilot",
            model="synthetic-model",
            run_label="test",
            ts=14,
        )
    )
    originals = {
        "cost-control.json": encoded(state),
        "cost-control.jsonl": encoded({"type": "synthetic.audit"}),
        "config.json": encoded({"synthetic": True}),
        f"projects/{project}/usage.jsonl": usage,
        f"projects/{project}/events.jsonl": events,
    }
    db = tmp_path / "generated.sqlite"
    with sqlite3.connect(db) as con:
        con.execute(
            "CREATE TABLE assistant_usage_events (id INTEGER PRIMARY KEY, session_id TEXT, model TEXT, input_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, output_tokens INTEGER, reasoning_tokens INTEGER, total_nano_aiu INTEGER, created_at TEXT)"
        )
        con.execute(
            "INSERT INTO assistant_usage_events VALUES (?,?,?,?,?,?,?,?,?,?)",
            (
                receipt_id,
                "known-session",
                "synthetic-model",
                11,
                2,
                0,
                3,
                0,
                model["total_nano_aiu"],
                12,
            ),
        )
    db_bytes = db.read_bytes()

    def cut(offset, data):
        return dict(offset=offset, length=len(data), sha256=digest(data))

    spec = dict(
        version=1,
        project_id=project,
        source_project_root=source,
        reservation_id="legacy-reservation",
        known_call_id="known-call",
        unknown_session_id="unknown-session",
        originals={name: digest(raw) for name, raw in originals.items()},
        usage_cuts=[cut(0, prefix)],
        event_cuts=[cut(0, part1), cut(second_offset, part2)],
        provider_evidence=dict(
            sqlite_sha256=digest(db_bytes), ids=[receipt_id], nano_aiu=model["total_nano_aiu"]
        ),
    )
    parent = tmp_path / "private"
    parent.mkdir(mode=0o700)
    with OfflineRecovery.create(parent, originals, db_bytes) as work:
        yield work, spec, state, originals, charge


def ready(work, spec):
    manifest = work.prepare(spec)
    result = work.apply_to_copy(
        manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"]
    )
    assert result["phase"] == "committed"
    return manifest


def assert_projection(work, spec, state, originals, charge):
    actual = work.read_state()
    assert actual["day"] == state["day"]
    assert actual["updated_at"] == state["updated_at"]
    assert actual["acknowledgements"] == state["acknowledgements"]
    assert actual["reservations"] == []
    assert len(actual["unresolved"]) == 1
    unknown = actual["unresolved"][0]
    assert unknown["call_id"] == "unknown-call" and unknown["pricing_status"] == "unknown"
    for key in ("observed_cost_usd", "observed_tokens", "created_at", "amount_usd", "project_root"):
        assert unknown[key] == state["reservations"][0][key]
    rows = strict_jsonl(
        work.root / f"projects/{spec['project_id']}/usage.jsonl", require_call_id=True
    )
    assert len(rows) == 1 and rows[0]["call_id"] == "known-call" and rows[0]["cost_usd"] == charge
    # Money is folded from the actual canonical ledger, not event count.
    summary = summarize_usage([UsageRecord.from_jsonable(r) for r in rows])
    assert summary.cost_usd == charge
    intent = json.loads(next((work.root / "cost-finalizers").glob("*.json")).read_bytes())
    validate_recovered(work.root, intent, unknown)
    archive = work.root / "accounting-recoveries" / unknown["recovery_provenance"]
    for name, raw in originals.items():
        assert (archive / "original" / name).read_bytes() == raw


def test_exact_charge_once_unknown_and_current_ack_preserved(case):
    work, spec, state, originals, charge = case
    manifest = ready(work, spec)
    assert_projection(*case)
    # Simulate a later supported approval in the private laboratory only.
    current = work.read_state()
    current["acknowledgements"]["unknown-call"] = dict(
        project_id=spec["project_id"], liability_usd=4, reason="Synthetic later review"
    )
    (work.root / "cost-control.json").write_bytes(encoded(current))
    before = (work.root / "cost-control.json").read_bytes()
    result = work.apply_to_copy(
        manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"]
    )
    assert result["duplicate"] is True
    assert (work.root / "cost-control.json").read_bytes() == before
    assert current["unresolved"][0]["pricing_status"] == "unknown"


@pytest.mark.parametrize(
    "point",
    [
        "before_projection",
        "usage",
        "events",
        "intent",
        "after:cost-control.json",
        "after_projection",
    ],
)
def test_durable_crash_boundaries_resume(case, point):
    work, spec, *_ = case
    manifest = work.prepare(spec)
    if point in {"usage", "events"}:
        point = f"after:projects/{spec['project_id']}/{point}.jsonl"
    if point == "intent":
        point = "after:" + next(n for n in manifest["order"] if n.startswith("cost-finalizers/"))

    def crash(stage):
        if stage == point:
            raise OSError("synthetic interruption")

    with pytest.raises(OSError, match="synthetic"):
        work.apply_to_copy(
            manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"], fault=crash
        )
    with pytest.raises(AccountingIntegrityError):
        work.read_state()
    work.apply_to_copy(manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"])
    assert_projection(*case)


@pytest.mark.parametrize(
    "field,value",
    [
        ("version", 2),
        ("version", True),
        ("extra", 0),
        ("project_id", "../escape"),
        ("source_project_root", "relative"),
    ],
)
def test_spec_rejected_before_archive(case, field, value):
    work, spec, *_ = case
