def snapshot(root):
    return {
        str(p.relative_to(root)): ("symlink", os.readlink(p))
        if p.is_symlink()
        else ("file", p.read_bytes())
        for p in root.rglob("*")
        if p.is_symlink() or p.is_file()
    }


@pytest.mark.parametrize("partial", [False, True])
@pytest.mark.parametrize(
    "target",
    [
        "project",
        "finalizers",
        "archive",
        "original",
        "projection",
        "segments",
        "manifest",
        "provider",
        "audit",
        "marker",
    ],
)
def test_all_archive_and_destination_rebinding_before_mutation(case, partial, target, tmp_path):
    work, spec, *_ = case
    manifest = work.prepare(spec)

    def run(**kw):
        return work.apply_to_copy(
            manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"], **kw
        )

    if partial:

        def interrupt(stage):
            if stage == "before_projection":
                raise OSError("synthetic interruption")

        with pytest.raises(OSError):
            run(fault=interrupt)
    archive = work.root / "accounting-recoveries" / manifest["id"]
    targets = {
        "project": work.root / "projects" / spec["project_id"],
        "finalizers": work.root / "cost-finalizers",
        "archive": archive,
        "original": archive / "original",
        "projection": archive / "projection",
        "segments": archive / "segments",
        "manifest": archive / "manifest.json",
        "provider": archive / "provider-evidence.db",
        "audit": archive / "audit.jsonl",
        "marker": work.root / "accounting-recovery.json",
    }
    path = targets[target]
    outside = tmp_path / "unrelated"
    if path.exists():
        path.rename(outside)
    elif target == "finalizers":
        outside.mkdir()
    else:
        outside.write_bytes(b"unrelated")
    path.symlink_to(outside, target_is_directory=outside.is_dir())
    before = snapshot(tmp_path)
    with pytest.raises((ValueError, OSError)):
        run()
    assert snapshot(tmp_path) == before


def test_resume_after_process_death(case):
    # Real child exit after a durable pending write; no runtime/provider started.
    work, spec, *_ = case
    manifest = work.prepare(spec)
    parent, name, token = work.root.parent, work.root.name, work.resume_token
    work.close()
    pid = os.fork()
    if pid == 0:
        with OfflineRecovery.resume(parent, name, resume_token=token) as child:

            def crash(stage):
                if stage == "after:cost-control.json":
                    os._exit(23)

            child.apply_to_copy(
                manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"], fault=crash
            )
        os._exit(24)
    _, status = os.waitpid(pid, 0)
    assert os.waitstatus_to_exitcode(status) == 23
    with OfflineRecovery.resume(parent, name, resume_token=token) as reopened:
        with pytest.raises(AccountingIntegrityError):
            reopened.read_state()
        reopened.apply_to_copy(manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"])
        assert_projection(reopened, *case[1:])


def test_wrong_resume_identity_rejected(case):
    work, *_ = case
    parent, name = work.root.parent, work.root.name
    work.close()
    before = snapshot(parent)
    with pytest.raises(ValueError, match="ownership"):
        OfflineRecovery.resume(parent, name, resume_token="incorrect")
    assert snapshot(parent) == before


def test_copy_lock_excludes_cooperating_reopen(case):
    from argus.core.cost_control import CostControlLockBusyError

    work, *_ = case
    with pytest.raises(CostControlLockBusyError):
        OfflineRecovery.resume(work.root.parent, work.root.name, resume_token=work.resume_token)


def test_late_directory_swap_cannot_redirect_replace(case, tmp_path, monkeypatch):
    import shutil

    work, spec, *_ = case
    manifest = work.prepare(spec)
    project = work.root / "projects" / spec["project_id"]
    outside, moved = tmp_path / "outside-copy", tmp_path / "moved-copy"
    shutil.copytree(project, outside)
    before = snapshot(outside)
    replace = os.replace

    def swapped(src, dst, **kwargs):
        if dst == "usage.jsonl" and not moved.exists():
            project.rename(moved)
            project.symlink_to(outside, target_is_directory=True)
        return replace(src, dst, **kwargs)

    monkeypatch.setattr(os, "replace", swapped)
    with pytest.raises((ValueError, OSError)):
        work.apply_to_copy(manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"])
    assert snapshot(outside) == before
    assert json.loads((work.root / "accounting-recovery.json").read_bytes())["phase"] == "pending"


def test_input_cannot_replace_ownership_lock(tmp_path):
    private = tmp_path / "private"
    private.mkdir(mode=0o700)
    with pytest.raises(ValueError):
        OfflineRecovery.create(private, {"offline-copy.lock": b"replacement"}, b"db")
    assert list(private.iterdir()) == []


@pytest.mark.parametrize("phase", ["unexpected", None, False])
def test_unknown_marker_never_authorizes_resume(case, phase):
    work, spec, *_ = case
    manifest = work.prepare(spec)
    (work.root / "accounting-recovery.json").write_bytes(
        encoded(dict(id=manifest["id"], manifest_sha256=manifest["manifest_sha256"], phase=phase))
    )
    before = snapshot(work.root)
    with pytest.raises(ValueError, match="modified recovery"):
        work.apply_to_copy(manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"])
    assert snapshot(work.root) == before


def test_unknown_manifest_fields_rejected_even_with_matching_hash(case):
    work, spec, *_ = case
    manifest = work.prepare(spec)
    target = work.root / "accounting-recoveries" / manifest["id"] / "manifest.json"
    modified = json.loads(target.read_bytes())
    modified["extra"] = True
    target.write_bytes(encoded(modified))
    before = snapshot(work.root)
    with pytest.raises(ValueError, match="bounded recovery manifest"):
        work.apply_to_copy(manifest["id"], expected_manifest_sha256=digest(target.read_bytes()))
    assert snapshot(work.root) == before


def test_archived_spec_is_transaction_bound(case):
    work, spec, *_ = case
    manifest = work.prepare(spec)
    target = work.root / "accounting-recoveries" / manifest["id"] / "spec.json"
    changed = json.loads(target.read_bytes())
    changed["unknown_session_id"] = "other-session"
    target.write_bytes(encoded(changed))
    before = snapshot(work.root)
    with pytest.raises(ValueError, match="specification identity"):
        work.apply_to_copy(manifest["id"], expected_manifest_sha256=manifest["manifest_sha256"])
    assert snapshot(work.root) == before
